const langButton=document.getElementById('language');
const nodes=[...document.querySelectorAll('[data-en]')];
nodes.forEach(n=>{if(!n.dataset.sv)n.dataset.sv=n.innerHTML});
let lang='en';try{lang=localStorage.getItem('yage-preferred-language')||'en'}catch{}
function setLanguage(next){lang=next==='sv'?'sv':'en';document.documentElement.lang=lang;nodes.forEach(n=>n.innerHTML=n.dataset[lang]);langButton.textContent=lang==='sv'?'EN':'SV';langButton.setAttribute('aria-label',lang==='sv'?'Switch to English':'Byt till svenska');document.title=lang==='sv'?'Yagé — Amazonas traditioner, med rötter i Sverige':'Yagé — Amazonian traditions, a Swedish connection';document.querySelector('meta[name="description"]').content=lang==='sv'?'En mötesplats för Amazonas traditioner i Sverige. Lär känna Yagé, få nyheter om kommande retreater och utforska våra rötter i Colombia.':'A meeting place for Amazonian traditions in Sweden. Get to know Yagé, receive retreat updates, and explore our roots in Colombia.';document.querySelectorAll('.dialog-close').forEach(b=>b.setAttribute('aria-label',lang==='sv'?'Stäng':'Close'));document.querySelectorAll('[data-en-alt]').forEach(n=>n.alt=n.dataset[lang+'Alt']);document.querySelectorAll('[data-en-aria]').forEach(n=>n.setAttribute('aria-label',n.dataset[lang+'Aria']));updateMenuLabel();updateMotionLabel();decorateArrows();}
langButton.addEventListener('click',()=>{setLanguage(lang==='sv'?'en':'sv');try{localStorage.setItem('yage-preferred-language',lang)}catch{}});
const menu=document.getElementById('menu-toggle'),nav=document.getElementById('nav'),header=document.getElementById('header');
function updateMenuLabel(){if(!menu)return;menu.setAttribute('aria-label',menu.getAttribute('aria-expanded')==='true'?(lang==='sv'?'Stäng meny':'Close menu'):(lang==='sv'?'Öppna meny':'Open menu'))}
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');header.classList.remove('menu-open');updateMenuLabel()}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);header.classList.toggle('menu-open',open);updateMenuLabel()});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const newsletter=document.getElementById('newsletter-dialog');document.querySelectorAll('.newsletter-open').forEach(b=>b.addEventListener('click',()=>{const holder=document.getElementById('newsletter-frame');if(!holder.firstChild){const frame=document.createElement('iframe');frame.src='https://baserow.caminoalsol.com/form/vpaVbSWgH7pXeopAG7PrGtDeGmf0x4alB2UOQQOvNJA';frame.title='Yagé — Retreat updates signup';frame.referrerPolicy='strict-origin-when-cross-origin';holder.append(frame)}newsletter.showModal();document.body.style.overflow='hidden'}));
document.getElementById('privacy-open').addEventListener('click',()=>{document.getElementById('privacy-dialog').showModal();document.body.style.overflow='hidden'});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()});d.addEventListener('close',()=>document.body.style.overflow='')});
function decorateArrows(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const list=[];while(walker.nextNode())if(walker.currentNode.textContent.includes('↗'))list.push(walker.currentNode);list.forEach(n=>{const fragment=document.createDocumentFragment();n.textContent.split('↗').forEach((text,i)=>{if(i){const a=document.createElement('i');a.className='arrow';a.setAttribute('aria-hidden','true');fragment.append(a)}fragment.append(document.createTextNode(text))});n.replaceWith(fragment)})}
const motionButton=document.getElementById('hero-motion-toggle'),hero=document.querySelector('.hero');
function updateMotionLabel(){const paused=motionButton.getAttribute('aria-pressed')==='true';motionButton.setAttribute('aria-label',lang==='sv'?(paused?'Spela bakgrundsanimation':'Pausa bakgrundsanimation'):(paused?'Play background animation':'Pause background animation'))}
motionButton.addEventListener('click',()=>{const paused=motionButton.getAttribute('aria-pressed')!=='true';motionButton.setAttribute('aria-pressed',String(paused));hero.classList.toggle('motion-paused',paused);updateMotionLabel()});
if('IntersectionObserver' in window)new IntersectionObserver(entries=>hero.classList.toggle('motion-offscreen',!entries[0].isIntersecting),{threshold:0}).observe(hero);
document.addEventListener('visibilitychange',()=>hero.classList.toggle('motion-hidden',document.hidden));
document.getElementById('year').textContent=new Date().getFullYear();setLanguage(lang);
